class Solution {
public:
    double average(vector<int>& salary) {
        long long sum = 0;
        int mn = INT_MAX, mx = INT_MIN;
        for (int s : salary) {
            sum += s;
            mn = min(mn, s);
            mx = max(mx, s);
        }
        sum -= mn;
        sum -= mx;
        return (double)sum / (salary.size() - 2);
    }
};
