class Solution {
public:
    string abbreviateProduct(int left, int right) {
        long long cnt2 = 0, cnt5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { x /= 2; cnt2++; }
            x = i;
            while (x % 5 == 0) { x /= 5; cnt5++; }
        }
        long long C = min(cnt2, cnt5);
        long long r2 = C, r5 = C;
        const long long MOD = 10000000000LL;
        long long prod = 1;
        bool overflow = false;
        long double sumlog = 0;
        for (int i = left; i <= right; i++) {
            long long x = i;
            while (x % 2 == 0 && r2 > 0) { x /= 2; r2--; }
            while (x % 5 == 0 && r5 > 0) { x /= 5; r5--; }
            prod *= x;
            if (prod >= MOD) { overflow = true; prod %= MOD; }
            sumlog += log10l((long double)i);
        }
        if (!overflow) {
            return to_string(prod) + "e" + to_string(C);
        }
        long double frac = sumlog - floorl(sumlog);
        long long prefix = (long long)floorl(powl(10.0L, frac + 4));
        if (prefix < 10000) prefix = 10000;
        if (prefix > 99999) prefix = 99999;
        long long suffix = prod % 100000;
        string suf = to_string(suffix);
        while (suf.size() < 5) suf = "0" + suf;
        return to_string(prefix) + "..." + suf + "e" + to_string(C);
    }
};
```

