class Solution {
public:
    vector<string> gen(const string& t) {
        vector<string> res;
        int n = t.size();
        if (n == 0) return res;
        // integer form
        if (n == 1 || t[0] != '0') res.push_back(t);
        // decimal forms
        for (int i = 1; i < n; ++i) {
            string a = t.substr(0, i), b = t.substr(i);
            if (a.size() > 1 && a[0] == '0') continue;
            if (b.back() == '0') continue;
            res.push_back(a + "." + b);
        }
        return res;
    }
    vector<string> ambiguousCoordinates(string s) {
        string t = s.substr(1, s.size() - 2);
        vector<string> ans;
        int n = t.size();
        for (int i = 1; i < n; ++i) {
            vector<string> L = gen(t.substr(0, i));
            vector<string> R = gen(t.substr(i));
            for (auto& a : L)
                for (auto& b : R)
                    ans.push_back("(" + a + ", " + b + ")");
        }
        return ans;
    }
};
```

