Classic reverse union-find approach: remove all hit bricks, union remaining with a virtual top node, then add hits back in reverse order and count how many bricks newly connect to the top.

```cpp
class Solution {
public:
    vector<int> parent, sz;
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> g = grid;
        for (auto& h : hits) {
            if (g[h[0]][h[1]] == 1) g[h[0]][h[1]] = 2; // mark as removed
        }
        int top = m * n;
        parent.resize(m * n + 1);
        sz.assign(m * n + 1, 1);
        for (int i = 0; i <= m * n; i++) parent[i] = i;
        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] != 1) continue;
                int id = i * n + j;
                if (i == 0) unite(id, top);
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;
                    if (g[ni][nj] == 1) unite(id, ni * n + nj);
                }
            }
        }
        vector<int> res(hits.size(), 0);
        for (int k = (int)hits.size() - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (g[r][c] != 2) continue;
            int before = sz[find(top)];
            g[r][c] = 1;
            int id = r * n + c;
            if (r == 0) unite(id, top);
            for (int d = 0; d < 4; d++) {
                int ni = r + dr[d], nj = c + dc[d];
                if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;
                if (g[ni][nj] == 1) unite(id, ni * n + nj);
            }
            int after = sz[find(top)];
            res[k] = max(0, after - before - 1);
        }
        return res;
    }
};
```

