class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        const long long MOD = 1000000007LL;
        sort(arr.begin(), arr.end());
        int n = arr.size();
        unordered_map<int, long long> dp;
        dp.reserve(n * 2);
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            long long ways = 1;
            for (int j = 0; j < i; ++j) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    auto it = dp.find(other);
                    if (it != dp.end()) {
                        ways = (ways + dp[arr[j]] * it->second) % MOD;
                    }
                }
            }
            dp[arr[i]] = ways;
            total = (total + ways) % MOD;
        }
        return (int)total;
    }
};
```

