class Solution {
public:
    int clumsy(int n) {
        std::vector<long long> st;
        st.push_back(n);
        int op = 0;
        for (int i = n - 1; i >= 1; --i) {
            if (op == 0) {
                st.back() *= i;
            } else if (op == 1) {
                st.back() /= i;
            } else if (op == 2) {
                st.push_back(i);
            } else {
                st.push_back(-i);
            }
            op = (op + 1) % 4;
        }
        long long sum = 0;
        for (long long v : st) sum += v;
        return (int)sum;
    }
};
```

