Use two Fenwick trees (count and sum) over values 1..1e5 with a queue of the last m elements. To compute the answer: sum of elements from rank k+1 to rank m-k = prefixSum(m-k) - prefixSum(k), where prefixSum(r) is the sum of the r smallest elements, found via BIT descent.

```cpp
class MKAverage {
    int m, k;
    static const int N = 100001;
    std::vector<long long> cnt, sum;
    std::deque<int> q;
    int LOG;

    void update(int i, long long c, long long s) {
        for (; i < N; i += i & -i) { cnt[i] += c; sum[i] += s; }
    }
    // sum of the r smallest elements
    long long prefixSum(long long r) {
        if (r <= 0) return 0;
        int pos = 0;
        long long res = 0;
        for (int b = LOG; b >= 0; --b) {
            int np = pos + (1 << b);
            if (np < N && cnt[np] < r) {
                pos = np;
                r -= cnt[np];
                res += sum[np];
            }
        }
        // remaining r elements all have value pos+1
        res += r * (long long)(pos + 1);
        return res;
    }
public:
    MKAverage(int m, int k) : m(m), k(k), cnt(N, 0), sum(N, 0) {
        LOG = 0;
        while ((1 << (LOG + 1)) < N) LOG++;
    }

    void addElement(int num) {
        q.push_back(num);
        update(num, 1, num);
        if ((int)q.size() > m) {
            int old = q.front();
            q.pop_front();
            update(old, -1, -old);
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        long long total = prefixSum(m - k) - prefixSum(k);
        return (int)(total / (m - 2 * k));
    }
};

