Classic DP: for each stone index i, keep the set of jump sizes that can land there. Since jump size after i stones is at most i+1, use a 2D boolean table dp[i][k] where k ≤ n.

```cpp
class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        if (n == 1) return true;
        if (stones[1] != 1) return false;
        // dp[i][k] = can reach stone i with last jump k
        vector<vector<char>> dp(n, vector<char>(n + 2, 0));
        dp[1][1] = 1;
        unordered_map<long long, int> pos;
        for (int i = 0; i < n; ++i) pos[stones[i]] = i;
        for (int i = 1; i < n; ++i) {
            for (int k = 1; k <= n; ++k) {
                if (!dp[i][k]) continue;
                for (int d = k - 1; d <= k + 1; ++d) {
                    if (d <= 0 || d > n) continue;
                    long long target = (long long)stones[i] + d;
                    auto it = pos.find(target);
                    if (it != pos.end()) {
                        dp[it->second][d] = 1;
                    }
                }
            }
        }
        for (int k = 1; k <= n; ++k) if (dp[n - 1][k]) return true;
        return false;
    }
};
```

