```cpp
class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        vector<vector<int>> g(m, vector<int>(m));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                g[i][j] = __gcd(nums[i], nums[j]);
        vector<int> dp(1 << m, 0);
        for (int mask = 0; mask < (1 << m); mask++) {
            int cnt = __builtin_popcount(mask);
            if (cnt % 2 != 0) continue;
            int op = cnt / 2 + 1;
            for (int i = 0; i < m; i++) {
                if (mask & (1 << i)) continue;
                for (int j = i + 1; j < m; j++) {
                    if (mask & (1 << j)) continue;
                    int nm = mask | (1 << i) | (1 << j);
                    dp[nm] = max(dp[nm], dp[mask] + op * g[i][j]);
                }
            }
        }
        return dp[(1 << m) - 1];
    }
};
```

