class Solution {
public:
    int countVowelSubstrings(string word) {
        int n = word.size();
        int count = 0;
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                if (!isVowel(word[j])) break;
                switch (word[j]) {
                    case 'a': mask |= 1; break;
                    case 'e': mask |= 2; break;
                    case 'i': mask |= 4; break;
                    case 'o': mask |= 8; break;
                    case 'u': mask |= 16; break;
                }
                if (mask == 31) count++;
            }
        }
        return count;
    }
};
```

