class CustomStack {
    vector<int> st;
    vector<int> lazy;
    int cap;
public:
    CustomStack(int maxSize) {
        cap = maxSize;
        lazy.assign(maxSize + 1, 0);
    }

    void push(int x) {
        if ((int)st.size() < cap) {
            st.push_back(x);
        }
    }

    int pop() {
        if (st.empty()) return -1;
        int idx = st.size() - 1;
        int val = st.back() + lazy[idx];
        if (idx > 0) lazy[idx - 1] += lazy[idx];
        lazy[idx] = 0;
        st.pop_back();
        return val;
    }

    void increment(int k, int val) {
        if (st.empty()) return;
        int idx = min(k, (int)st.size()) - 1;
        lazy[idx] += val;
    }
};

