Sliding window approach: for a window [l, r] of fruit indices, the cost to cover it is `min(|start-pos[l]|, |start-pos[r]|) + (pos[r]-pos[l])`. Expand r, shrink l while the cost exceeds k.

```cpp
class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        int n = fruits.size();
        long long sum = 0;
        int best = 0;
        int l = 0;
        auto cost = [&](int l, int r) {
            int pl = fruits[l][0], pr = fruits[r][0];
            long long span = pr - pl;
            long long dl = abs(startPos - pl), dr = abs(startPos - pr);
            return span + min(dl, dr);
        };
        for (int r = 0; r < n; r++) {
            sum += fruits[r][1];
            while (l <= r && cost(l, r) > k) {
                sum -= fruits[l][1];
                l++;
            }
            if (l <= r) best = max(best, (int)sum);
        }
        return best;
    }
};
```

