Use reverse-graph topological sort (Kahn's algorithm): nodes whose out-degree reaches 0 are safe.

```cpp
class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> rev(n);
        vector<int> outdeg(n);
        for (int i = 0; i < n; ++i) {
            outdeg[i] = graph[i].size();
            for (int j : graph[i]) rev[j].push_back(i);
        }
        queue<int> q;
        vector<bool> safe(n, false);
        for (int i = 0; i < n; ++i) if (outdeg[i] == 0) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            safe[u] = true;
            for (int v : rev[u]) {
                if (--outdeg[v] == 0) q.push(v);
            }
        }
        vector<int> res;
        for (int i = 0; i < n; ++i) if (safe[i]) res.push_back(i);
        return res;
    }
};
```

