        int m = grid.size(), n = grid[0].size();
        vector<vector<long long>> rowPre(m, vector<long long>(n + 1, 0));
        vector<vector<long long>> colPre(m + 1, vector<long long>(n, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                rowPre[i][j + 1] = rowPre[i][j] + grid[i][j];
        for (int j = 0; j < n; j++)
            for (int i = 0; i < m; i++)
                colPre[i + 1][j] = colPre[i][j] + grid[i][j];
        int best = 1;
        for (int k = min(m, n); k >= 2; k--) {
            for (int i = 0; i + k <= m; i++) {
                for (int j = 0; j + k <= n; j++) {
                    long long target = rowPre[i][j + k] - rowPre[i][j];
                    bool ok = true;
                    for (int r = i; r < i + k && ok; r++) {
                        if (rowPre[r][j + k] - rowPre[r][j] != target) ok = false;
