Classic approach: sort, cap at target, use suffix sums to complete gardens from the largest, and for the remaining prefix use two-pointer/binary search to find the max achievable minimum.

```cpp
class Solution {
public:
    long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
        int n = flowers.size();
        vector<long long> a(n);
        for (int i = 0; i < n; i++) a[i] = min((long long)flowers[i], (long long)target);
        sort(a.begin(), a.end());
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        // cost to complete suffix starting at index i: (n-i)*target - (pre[n]-pre[i])
        long long best = 0;
        // number of already-complete gardens
        // iterate i = number of incomplete gardens (prefix of length i), suffix [i, n) completed
        int j = 0; // pointer for prefix such that we can raise a[0..j-1] to some level
        for (int i = n; i >= 0; i--) {
            long long cost = (long long)(n - i) * target - (pre[n] - pre[i]);
            if (cost > newFlowers) break;
            long long rem = newFlowers - cost;
            long long val = (long long)(n - i) * full;
            if (i > 0) {
                // find max level m < target such that we can raise a[0..i-1] to at least m
                // binary search on k = number of gardens raised (largest k in [1,i]) -> level
                int lo = 0, hi = i; // find largest k such that a[k-1]*k - pre[k] <= rem
                // f(k) = a[k-1]*k - pre[k] is nondecreasing in k
                while (lo < hi) {
                    int mid = (lo + hi + 1) / 2;
                    if (a[mid - 1] * mid - pre[mid] <= rem) lo = mid;
                    else hi = mid - 1;
                }
                int k = lo; // k >= 1 since f(1)=0
                long long level = (pre[k] + rem) / k;
                if (k < i) level = min(level, a[k]);
                level = min(level, (long long)target - 1);
                val += level * partial;
            }
            best = max(best, val);
        }
        return best;
    }
};
```

