class Solution {
public:
    int minMalwareSpread(vector<vector<int>>& graph, vector<int>& initial) {
        int n = graph.size();
        vector<bool> isInit(n, false);
        for (int x : initial) isInit[x] = true;
        // reach[v] = set of initial nodes reaching v via clean nodes; store count and one source
        vector<int> cnt(n, 0), src(n, -1);
        for (int s : initial) {
            vector<bool> vis(n, false);
            vector<int> st;
            st.push_back(s);
            vis[s] = true;
            while (!st.empty()) {
                int u = st.back(); st.pop_back();
                for (int v = 0; v < n; v++) {
                    if (graph[u][v] && !vis[v] && !isInit[v]) {
                        vis[v] = true;
                        cnt[v]++;
                        src[v] = s;
                        st.push_back(v);
                    }
                }
            }
        }
        vector<int> save(n, 0);
        for (int v = 0; v < n; v++) {
            if (!isInit[v] && cnt[v] == 1) save[src[v]]++;
        }
        int best = -1, bestSave = -1;
        sort(initial.begin(), initial.end());
        for (int s : initial) {
            if (save[s] > bestSave) {
                bestSave = save[s];
                best = s;
            }
        }
        return best;
    }
};
