                    auto it = lastX.find(key);
                    if (it != lastX.end()) {
                        long long area = (long long)(x - it->second) * (ys[j] - ys[i]);
                        if (area < best) best = area;
                    }
                    lastX[key] = x;
                }
            }
        }
        return best == LLONG_MAX ? 0 : (int)best;
    }
};
