Classic approach: recursively split the array by root into left (smaller) and right (larger) subsequences; number of interleavings is C(l+r, l) times ways(left) times ways(right). Use Pascal's triangle for binomials mod 1e9+7, and subtract 1 at the end.

```cpp
class Solution {
public:
    static const int MOD = 1000000007;
    vector<vector<int>> C;

    long long ways(vector<int>& a) {
        int n = a.size();
        if (n <= 2) return 1;
        vector<int> left, right;
        for (int i = 1; i < n; i++) {
            if (a[i] < a[0]) left.push_back(a[i]);
            else right.push_back(a[i]);
        }
        long long res = C[n - 1][left.size()];
        res = res * ways(left) % MOD;
        res = res * ways(right) % MOD;
        return res;
    }

    int numOfWays(vector<int>& nums) {
        int n = nums.size();
        C.assign(n + 1, vector<int>(n + 1, 0));
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + (j <= i - 1 ? C[i - 1][j] : 0)) % MOD;
            }
        }
        long long r = ways(nums);
        return (int)((r - 1 + MOD) % MOD);
    }
};
```

