class Solution {
public:
    long long countType(vector<int>& A, vector<int>& B) {
        unordered_map<long long, long long> freqB;
        for (int b : B) freqB[b]++;
        vector<long long> distinctB;
        for (auto& p : freqB) distinctB.push_back(p.first);
        unordered_map<long long, long long> freqA;
        for (int a : A) freqA[a]++;
        long long total = 0;
        for (auto& pa : freqA) {
            long long x = pa.first;
            long long sq = x * x;
            long long cnt = 0;
            for (long long a : distinctB) {
                if (sq % a != 0) continue;
                long long b = sq / a;
                if (a > b) continue;
                auto it = freqB.find(b);
                if (it == freqB.end()) continue;
                if (a == b) {
                    cnt += freqB[a] * (freqB[a] - 1) / 2;
