class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        for (int x : nums) if (x > target) return false;
        int full = 1 << n;
        vector<char> dp(full, 0);
        vector<int> sum(full, 0);
        dp[0] = 1;
        for (int mask = 0; mask < full; ++mask) {
            if (!dp[mask]) continue;
            int cur = sum[mask] % target;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (cur + nums[i] <= target) {
                    int nm = mask | (1 << i);
                    if (!dp[nm]) {
                        dp[nm] = 1;
                        sum[nm] = sum[mask] + nums[i];
                    }
                }
            }
        }
        return dp[full - 1];
    }
};
```

