Binary search on the answer: for a candidate maximum sum, greedily count how many subarrays are needed; if the count is at most k, the candidate is feasible.

```cpp
class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long lo = 0, hi = 0;
        for (int x : nums) {
            lo = max(lo, (long long)x);
            hi += x;
        }
        auto feasible = [&](long long cap) {
            int count = 1;
            long long cur = 0;
            for (int x : nums) {
                if (cur + x > cap) {
                    count++;
                    cur = x;
                    if (count > k) return false;
                } else {
                    cur += x;
                }
            }
            return true;
        };
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};
```

