class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.size();
        int n = stickers.size();
        vector<vector<int>> cnt(n, vector<int>(26, 0));
        for (int i = 0; i < n; i++)
            for (char c : stickers[i]) cnt[i][c - 'a']++;
        int full = (1 << m) - 1;
        vector<int> dp(1 << m, INT_MAX);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << m); mask++) {
            if (dp[mask] == INT_MAX) continue;
            for (int i = 0; i < n; i++) {
                vector<int> c = cnt[i];
                int nm = mask;
                for (int j = 0; j < m; j++) {
                    if (nm & (1 << j)) continue;
                    int ch = target[j] - 'a';
                    if (c[ch] > 0) {
                        c[ch]--;
                        nm |= (1 << j);
                    }
                }
                if (nm != mask && dp[mask] + 1 < dp[nm]) dp[nm] = dp[mask] + 1;
            }
        }
        return dp[full] == INT_MAX ? -1 : dp[full];
    }
};
```

