Classic union-find approach: split each cell into 4 triangles (top=0, right=1, bottom=2, left=3), union within cell based on the character, and union adjacent cells' touching triangles.

```cpp
class Solution {
public:
    vector<int> parent;
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra != rb) parent[ra] = rb;
    }
    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        parent.resize(4 * n * n);
        for (int i = 0; i < 4 * n * n; i++) parent[i] = i;
        auto id = [&](int r, int c, int k) { return (r * n + c) * 4 + k; };
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r][c];
                if (ch == ' ') {
                    unite(id(r, c, 0), id(r, c, 1));
                    unite(id(r, c, 1), id(r, c, 2));
                    unite(id(r, c, 2), id(r, c, 3));
                } else if (ch == '/') {
                    unite(id(r, c, 0), id(r, c, 3));
                    unite(id(r, c, 1), id(r, c, 2));
                } else { // '\\'
                    unite(id(r, c, 0), id(r, c, 1));
                    unite(id(r, c, 2), id(r, c, 3));
                }
                if (r + 1 < n) unite(id(r, c, 2), id(r + 1, c, 0));
                if (c + 1 < n) unite(id(r, c, 1), id(r, c + 1, 3));
            }
        }
        int count = 0;
        for (int i = 0; i < 4 * n * n; i++) {
            if (find(i) == i) count++;
        }
        return count;
    }
};
```

