```cpp
class Solution {
public:
    int sumOddLengthSubarrays(vector<int>& arr) {
        int n = arr.size();
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            long long cnt = (long long)(i + 1) * (n - i);
            long long odd = (cnt + 1) / 2;
            total += odd * arr[i];
        }
        return (int)total;
    }
};
