Classic approach: DFS from root, maintaining for each value 1..50 a stack of (node, depth) of ancestors with that value. For each node, check all values coprime with nums[node], take the deepest ancestor among stack tops. Use iterative DFS to avoid stack overflow for n up to 1e5.

```cpp
class Solution {
public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        bool cop[51][51];
        for (int i = 1; i <= 50; i++)
            for (int j = 1; j <= 50; j++)
                cop[i][j] = (__gcd(i, j) == 1);
        vector<vector<pair<int,int>>> st(51); // value -> stack of (node, depth)
        vector<int> ans(n, -1);
        vector<int> depth(n, 0), parent(n, -1), idx(n, 0);
        // iterative DFS
        vector<int> stack;
        stack.push_back(0);
        parent[0] = -1;
        depth[0] = 0;
        // on entering node
        auto enter = [&](int u) {
            int best = -1, bestDepth = -1;
            for (int v = 1; v <= 50; v++) {
                if (cop[nums[u]][v] && !st[v].empty()) {
                    auto& p = st[v].back();
                    if (p.second > bestDepth) {
                        bestDepth = p.second;
                        best = p.first;
                    }
                }
            }
            ans[u] = best;
            st[nums[u]].push_back({u, depth[u]});
        };
        enter(0);
        while (!stack.empty()) {
            int u = stack.back();
            if (idx[u] < (int)adj[u].size()) {
                int v = adj[u][idx[u]++];
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                enter(v);
                stack.push_back(v);
            } else {
                st[nums[u]].pop_back();
                stack.pop_back();
            }
        }
        return ans;
    }
};
```

