Standard spiral walk: step lengths go 1,1,2,2,3,3,... with directions east, south, west, north; record cells inside the grid until all rows*cols are collected.

```cpp
class Solution {
public:
    vector<vector<int>> spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        vector<vector<int>> res;
        int total = rows * cols;
        int dr[4] = {0, 1, 0, -1};
        int dc[4] = {1, 0, -1, 0};
        int r = rStart, c = cStart;
        res.push_back({r, c});
        int len = 1;
        int dir = 0;
        while ((int)res.size() < total) {
            for (int k = 0; k < 2; ++k) {
                for (int s = 0; s < len; ++s) {
                    r += dr[dir];
                    c += dc[dir];
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        res.push_back({r, c});
                        if ((int)res.size() == total) return res;
                    }
                }
                dir = (dir + 1) % 4;
            }
            ++len;
        }
        return res;
    }
};
```

