traces.inference_trace:
Classic approach: assign coefficients to each character (sum of powers of 10 from words minus powers from result), then backtrack assigning digits to unique characters, checking that the weighted sum is zero at the end and that no leading zeros occur. With at most 10 characters, 10! permutations worst-case is fine, especially with pruning by column-wise approach; the coefficient approach with pruning works well too.

I'll use the column-by-column backtracking for efficiency.

```cpp
class Solution {
public:
    vector<string> w;
    string res;
    int mp[26];
    bool used[10];
    bool nonzero[26];
    int maxLen;

    bool dfs(int col, int idx, int carry) {
        if (col == maxLen) {
            return carry == 0;
        }
        if (idx == (int)w.size()) {
            // handle result digit at this column
            int sum = carry;
            for (auto& s : w) {
                if (col < (int)s.size()) sum += mp[s[s.size() - 1 - col] - 'A'];
            }
            int d = sum % 10;
            int c = sum / 10;
            char ch = res[res.size() - 1 - col];
            int ci = ch - 'A';
            if (mp[ci] != -1) {
                if (mp[ci] != d) return false;
                return dfs(col + 1, 0, c);
            } else {
                if (used[d]) return false;
                if (d == 0 && nonzero[ci]) return false;
                mp[ci] = d;
                used[d] = true;
                bool ok = dfs(col + 1, 0, c);
                mp[ci] = -1;
                used[d] = false;
                return ok;
            }
        }
        const string& s = w[idx];
        if (col >= (int)s.size()) return dfs(col, idx + 1, carry);
        int ci = s[s.size() - 1 - col] - 'A';
