```cpp
class Solution {
public:
    string strWithout3a3b(int a, int b) {
        string s;
        while (a > 0 || b > 0) {
            int n = s.size();
            bool lastTwoA = n >= 2 && s[n-1] == 'a' && s[n-2] == 'a';
            bool lastTwoB = n >= 2 && s[n-1] == 'b' && s[n-2] == 'b';
            if (lastTwoA) {
                s.push_back('b');
                b--;
            } else if (lastTwoB) {
                s.push_back('a');
                a--;
            } else if (a >= b) {
                s.push_back('a');
                a--;
            } else {
                s.push_back('b');
                b--;
            }
        }
        return s;
    }
};
