Compute indegrees; exactly one node must have indegree 0 (the root), all others indegree 1. Then BFS/DFS from the root and check all n nodes are reachable.

```cpp
class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> indeg(n, 0);
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) indeg[leftChild[i]]++;
            if (rightChild[i] != -1) indeg[rightChild[i]]++;
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            } else if (indeg[i] > 1) {
                return false;
            }
        }
        if (root == -1) return false;
        vector<bool> vis(n, false);
        vector<int> st;
        st.push_back(root);
        vis[root] = true;
        int cnt = 0;
        while (!st.empty()) {
            int u = st.back(); st.pop_back();
            cnt++;
            int c[2] = {leftChild[u], rightChild[u]};
            for (int v : c) {
                if (v == -1) continue;
                if (vis[v]) return false;
                vis[v] = true;
                st.push_back(v);
            }
        }
        return cnt == n;
    }
};
```

